import {EXPEDITIONS,getExpedition,normalizeExpeditionProgress,expeditionUnlocked} from './expedition.js';
const details=[['거리·마트','끊긴 무전과 병원 이송 기록'],['옥상','연결교를 건너 병원 채널 확보'],['병원','원액의 냉각 기록과 화물 번호'],['북한 검역 회랑','기록 차량을 호위해 해상 송장 확보'],['해상 항만','두 중계기를 오가며 항로 개방'],['이스라엘 하이파','K-17 배양 계통 대조'],['성가대 격리소','최종 보관체 처치·백신 회수·탈출']];
export function storyRouteModel(progress,{activeId=null,qaUnlocked=false}={}){
 const state=normalizeExpeditionProgress(progress);
 return EXPEDITIONS.map((definition,index)=>({definition,index,place:definition.optional?definition.title.replace('마지막 신호 · ',''):details[index]?.[0]||definition.title,detail:definition.optional?(definition.routeDetail||'선택 분기 · '+definition.subtitle):details[index]?.[1]||definition.subtitle,cleared:state.cleared.includes(definition.id),active:definition.id===activeId,unlocked:qaUnlocked||expeditionUnlocked(state,definition.id),requires:getExpedition(definition.requires)?.title.replace('마지막 신호 · ','')||null}));
}
export function storyRouteHTML(progress,options={}){
 const model=storyRouteModel(progress,options),main=model.filter(n=>!n.definition.optional),side=model.filter(n=>n.definition.optional),done=main.filter(n=>n.cleared).length;
 const card=n=>`<button class="mission-node story-stop ${n.unlocked||n.active?'':'locked'} ${n.active?'selected':''}" data-action="${n.active?'continue':'expedition'}" data-value="${n.definition.id}" ${n.unlocked||n.active?'':'disabled'} ${n.active?'aria-current="location"':''}><span class="mission-number">${n.definition.optional?'+':String(n.index+1).padStart(2,'0')}</span><span><strong>${n.place}</strong><small>${n.detail}</small><small class="story-status">${n.active?'진행 중인 작전 · 이어하기':n.cleared?'✓ 회수 완료':n.unlocked?'출격 가능':n.requires+' 완료 후 해금'}</small></span></button>`;
 return `<section class="panel campaign-panel story-route-panel" aria-label="백신 탐색 원정 지도"><p class="eyebrow">LAST SIGNAL / 마지막 신호</p><h2>백신을 찾아가는 여정</h2><p class="muted">한도윤과 서윤서가 K-17의 이송 기록을 따라갑니다. 기록을 찾고, 길을 열고, 마지막 격리소에서 백신을 회수하세요.</p><div class="campaign-summary"><span>핵심 원정 ${done} / ${main.length} 완료</span><span>${done===main.length?'첫 백신 원액 회수 기록 확보':'백신의 행방을 추적 중'}</span></div><ol class="story-route-chain" aria-label="연결된 핵심 경로">${main.map(n=>`<li class="${n.cleared?'cleared':''} ${n.active?'current':''}">${n.cleared?'✓ ':''}${n.place}</li>`).join('')}</ol><div class="mission-map story-stops">${main.map(card).join('')}</div><h3>여정 중 선택할 수 있는 우회</h3><p class="muted">필수 경로를 유지하면서 운송에 필요한 준비를 더합니다.</p><div class="mission-map story-branches">${side.map(card).join('')}</div><div class="panel-actions"><span class="muted">원정을 고르면 장비와 목표를 확인할 수 있습니다.</span><button class="secondary" data-action="story-records">회수 기록</button><button class="secondary" data-action="menu">메인 메뉴</button></div></section>`;
}
